  "Yuanwu": { s1: "Taza humeante de justicia", s2: "Corazón feroz, mente serena", s3: "Defensor de la integridad", s4: "Nudillos retributivos", s5: "Protector del vecindario", s6: "Defensor de todos los reinos" },
  "Mortefi": { s1: "Estudio solitario", s2: "Himno hipócrita", s3: "Recitativo en llamas", s4: "Vals catártico", s5: "Cuarteto fúnebre", s6: "Instrumental apoplético" },
  "Youhu": { s1: "Descanso junto al agua", s2: "Siesta en el invernadero", s3: "Sueño inquieto", s4: "Nana escarchada", s5: "Deambular por el país de los sueños", s6: "Sueño eterno" },
